function out(array $d,int $s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function def():array{return ['revision'=>0,'journals'=>[],'bagSupplierBills'=>[],'bagSupplierPayments'=>[],'bankAccountSettings'=>[]];}
function readStore():array{tt_ensure_data_dir();if(!is_file(TT_BSP_FILE))return def();$h=fopen(TT_BSP_FILE,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);} $v=$raw?json_decode($raw,true):null;return is_array($v)?array_replace_recursive(def(),$v):def();}
function canWrite(array $u):bool{if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function ent(string $v):string{$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))out(['ok'=>false,'error'=>'Bag supplier payments are available for TTI or BRM books.'],422);return $v;}
function datev(string $v):string{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$v))out(['ok'=>false,'error'=>'Valid payment date required.'],422);return $v;}
