function nextId(array $a,string $p):string{$n=count($a)+1;do{$id=$p.'-'.gmdate('Y').'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);$n++;}while(isset($a[$id]));return $id;}
function paid(array $s,string $billId):float{$n=0.0;foreach((array)($s['bagSupplierPayments']??[]) as $p){if(!is_array($p)||($p['status']??'')==='Cancelled')continue;if((string)($p['billId']??'')===$billId)$n+=(float)($p['amount']??0);}return round($n,2);}
