function bankMaster(string $id,string $entity):array{$masters=tt_list_masters();foreach((array)($masters['banks']??[]) as $r){if(!is_array($r)||(string)($r['id']??'')!==$id)continue;$v=array_values((array)($r['values']??[]));while(count($v)<14)$v[]='';$linked=strtoupper((string)$v[1]);$be=str_contains($linked,'BRM')||str_contains($linked,'BUKSH RICE')?'BRM':(str_contains($linked,'TTI')||str_contains($linked,'TRANSTRADE INTERNATIONAL')?'TTI':'');if($be!==$entity)out(['ok'=>false,'error'=>'Selected bank account does not belong to these company books.'],422);if(strtoupper(trim((string)$v[7]))!=='PKR')out(['ok'=>false,'error'=>'Bag supplier payments must use a PKR bank account.'],422);return ['id'=>$id,'name'=>(string)$v[4],'title'=>(string)$v[3]];}out(['ok'=>false,'error'=>'Selected bank account was not found.'],404);}
function banks(array $s,string $e):array{$masters=tt_list_masters();$o=[];foreach((array)($masters['banks']??[]) as $r){if(!is_array($r))continue;$v=array_values((array)($r['values']??[]));while(count($v)<14)$v[]='';$linked=strtoupper((string)$v[1]);$be=str_contains($linked,'BRM')||str_contains($linked,'BUKSH RICE')?'BRM':(str_contains($linked,'TTI')||str_contains($linked,'TRANSTRADE INTERNATIONAL')?'TTI':'');$id=(string)($r['id']??'');$set=is_array($s['bankAccountSettings'][$id]??null)?$s['bankAccountSettings'][$id]:[];if($be!==$e||trim((string)$v[0])!=='Company Account'||strtoupper(trim((string)$v[7]))!=='PKR'||!tt_bank_can_transact($id))continue;$o[]=['id'=>$id,'display'=>trim((string)$v[4]).' — '.trim((string)$v[3])];}return $o;}
function payload(array $s,string $e):array{return ['ok'=>true,'entity'=>$e,'payables'=>billRows($s,$e),'banks'=>banks($s,$e),'history'=>array_values(array_filter((array)($s['bagSupplierPayments']??[]),static fn($p)=>is_array($p)&&($p['entity']??'')===$e)),'serverNow'=>gmdate('c')];}
try{$u=tt_require_login();if(!tt_user_can_open_module($u,'Accounts'))out(['ok'=>false,'error'=>'Accounts permission required.'],403);$e=ent((string)($_GET['entity']??$_POST['entity']??'TTI'));if($_SERVER['REQUEST_METHOD']==='GET')out(payload(readStore(),$e));if($_SERVER['REQUEST_METHOD']!=='POST')out(['ok'=>false,'error'=>'Method not allowed.'],405);if(!canWrite($u))out(['ok'=>false,'error'=>'Accounts Create / Edit / Approve permission required.'],403);$b=json_decode(file_get_contents('php://input')?:'{}',true);if(!is_array($b)||!tt_verify_csrf((string)($b['csrf']??'')))out(['ok'=>false,'error'=>'Your session expired. Refresh and try again.'],419);if((string)($b['action']??'')!=='pay_bill')out(['ok'=>false,'error'=>'Unknown bag supplier payment action.'],422);$e=ent((string)($b['entity']??''));$billId=trim((string)($b['billId']??''));$date=datev((string)($b['date']??''));$amt=money($b['amount']??0);$method=(string)($b['method']??'Bank');$bankId=trim((string)($b['bankId']??''));$ref=trim((string)($b['reference']??''));if($method!=='Bank')out(['ok'=>false,'error'=>'Bag supplier bills can only be paid through a company bank account.'],422);if($bankId==='')out(['ok'=>false,'error'=>'Select the company bank account paying this bag supplier bill.'],422);$s=readStore();$bill=$s['bagSupplierBills'][$billId]??null;if(!is_array($bill)||($bill['entity']??'')!==$e||($bill['status']??'')!=='Posted')out(['ok'=>false,'error'=>'Bag supplier bill is not available for payment in these company books.'],404);$outstanding=max(0,round((float)$bill['totalAmount']-paid($s,$billId),2));if($outstanding<=.005)out(['ok'=>false,'error'=>'This bag supplier bill is already fully paid.'],409);if(abs($amt-$outstanding)>.005)out(['ok'=>false,'error'=>'Partial payment is not allowed for bag supplier bills. Pay the full outstanding invoice amount.'],422);$bank=bankMaster($bankId,$e);$set=is_array($s['bankAccountSettings'][$bankId]??null)?$s['bankAccountSettings'][$bankId]:[];if(!tt_bank_can_transact($